const d=$json||{}; const action=String(d.action||'').toLowerCase();
if(['approve','reject'].includes(action)) return [{json:{...d,decision:action==='approve'?'Approved':'Rejected',decision_valid:true,approval_id:String(d.approval_id||'')}}];
const amount=Number(d.amount||0); const et=String(d.entity_type||'').toLowerCase();
const required=amount>1000 || (['customer','order','ticket'].includes(et)&&action==='delete');
if(!required) return [{json:{...d,approval_required:false,approval_status:'Auto Approved'}}];
return [{json:{...d,approval_id:String(d.approval_id||`APR-${Date.now()}`),approval_required:true,approval_status:'Pending'}}];

const j=$('Prepare Approval').first().json; const et=String(j.entity_type||'Invoice');
const label=et==='Customer'?`العميل: ${j.customer_name||j.customer_id||j.entity_id||'-'}`:et==='Order'?`الطلب: ${j.order_id||j.entity_id||'-'}`:et==='Ticket'?`التذكرة: ${j.ticket_id||j.entity_id||'-'}`:`الفاتورة: ${j.invoice_number||j.invoice_id||j.entity_id||'-'}
المبلغ: ${j.amount||'-'}`;
return [{json:{...j,manager_chat_id:'YOUR_MANAGER_CHAT_ID',reply:`🔔 طلب موافقة جديد

${label}
رقم الموافقة: ${j.approval_id}

اضغط أحد الأزرار أدناه لاتخاذ القرار.`,result_type:'approval_request'}}];

const base = $('Update Approval Decision').first().json || {};
const cur = $json || {};
const d = { ...base, ...cur };

// Use the recorded decision, with status as a fallback.
const decision = d.decision || d.status;

const approved = decision === 'Approved';
const rejected = decision === 'Rejected';

let reply = approved
  ? `✅ تمت الموافقة على ${d.approval_id || ''}.`
  : rejected
    ? `❌ تم رفض ${d.approval_id || ''}.`
    : `⚠️ تعذّر تحديد نتيجة الموافقة للطلب ${d.approval_id || ''}.`;

if (approved && d.delete_completed === true) {
  reply = `🗑️ تمت الموافقة على حذف ${d.entity_type || ''} ${d.entity_id || ''} وتنفيذ الحذف.`;
}

if (d.delete_found === false || d.invoice_found === false) {
  reply = d.reply || `⚠️ لم يتم العثور على العنصر المطلوب ${d.entity_id || ''}.`;
}

return [{
  json: {
    ...d,
    decision,
    reply,
    audit_action: d.action === 'delete'
      ? 'delete'
      : approved
        ? 'approve'
        : rejected
          ? 'reject'
          : 'unknown',
    audit_status:
      decision === 'Approved' || decision === 'Rejected'
        ? 'success'
        : 'failed'
  }
}];
